    static final int WARN_OWNERS_PER_CITY = 40;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerCityCapacityException {
        String city = request.getCity();
        int count = countOwnersInCity(ownerRepository, city);
        if (count >= MAX_OWNERS_PER_CITY) {
            throw new OwnerCityCapacityException(city, count);
        }
    }

    /**
     * The number of existing owners whose city matches {@code city} case-insensitively with surrounding
     * whitespace trimmed. On a create the new owner is still unsaved, so it is not among those counted.
     */
    static int countOwnersInCity(OwnerRepository ownerRepository, String city) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsNormalized(city, existing.getCity())) {
                count++;
            }
        }
        return count;
    }

    private static boolean equalsNormalized(String a, String b) {
        if (a == null || b == null) {
            return a == null && b == null;
        }
        return a.trim().equalsIgnoreCase(b.trim());
    }
}

